mapper.sql:
WHERE 1=1
AND ENTITY_TYPE = #{entityType}
AND ENTITY_ID = #{entityId}
AND USER_ID = #{userId}
AND ACTION_CD = #{actionCd}
AND TRACE_ID = #{traceId}

mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT HIST_ID, TRACE_ID, USER_ID, ORG_CD, SERVICE_ID, ENTITY_TYPE, ENTITY_ID,
           ACTION_CD, RESULT_CD, REASON_TXT, EVENT_DTM
      FROM TB_EOS_CHG_HIST

     ORDER BY EVENT_DTM DESC
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}
